draw:
var g = 9.8;
var sag = p.mass * g / p.k;
var omega = Math.sqrt(p.k / p.mass);
var A = p.amplitude;
var u = A * Math.cos(omega * t);
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 2;

var topY = H * 0.12;
var scale = (H * 0.52) / Math.max(sag + A, 0.02);
if (scale > 900) { scale = 900; }
var natural = H * 0.34;
var colX = [W * 0.20, W * 0.50, W * 0.80];

function coil(cx, y0, y1) {
  ctx.strokeStyle = C.accent;
  ctx.beginPath();
  ctx.moveTo(cx, y0);
  var i;
  for (i = 1; i <= 12; i++) {
    var yy = y0 + (y1 - y0) * i / 12;
    var xx = cx + (i % 2 === 0 ? -10 : 10) * (i === 12 ? 0 : 1);
    ctx.lineTo(xx, yy);
  }
  ctx.lineTo(cx, y1);
  ctx.stroke();
}

ctx.strokeStyle = C.faint;
ctx.lineWidth = 3;
ctx.beginPath(); ctx.moveTo(W * 0.08, topY); ctx.lineTo(W * 0.92, topY); ctx.stroke();
ctx.lineWidth = 2;
ctx.fillStyle = C.faint;
ctx.fillText("ceiling", W * 0.08, topY - 8);

var labels = ["no load", "hanging at rest", "oscillating"];
var ends = [natural, natural + sag * scale, natural + (sag + u) * scale];
var i;
for (i = 0; i < 3; i++) {
  coil(colX[i], topY, ends[i]);
  if (i > 0) {
    ctx.fillStyle = C.figure;
    ctx.fillRect(colX[i] - 16, ends[i], 32, 24);
  }
  ctx.fillStyle = C.faint;
  ctx.fillText(labels[i], colX[i] - 34, H * 0.95);
}

ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(colX[0] - 20, natural); ctx.lineTo(colX[2] + 30, natural); ctx.stroke();
var eqY = natural + sag * scale;
ctx.beginPath(); ctx.moveTo(colX[1] - 20, eqY); ctx.lineTo(colX[2] + 30, eqY); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.faint;
ctx.fillText("natural length", colX[0] - 20, natural - 6);
ctx.fillStyle = C.accent;
ctx.fillText("equilibrium", colX[2] - 10, eqY - 6);

ctx.strokeStyle = C.accent;
ctx.beginPath();
ctx.moveTo(colX[1] + 44, natural);
ctx.lineTo(colX[1] + 44, eqY);
ctx.stroke();
ctx.fillStyle = C.accent;
ctx.fillText("mg/k", colX[1] + 48, (natural + eqY) / 2 + 4);

out.note = "sag mg/k = " + sag.toFixed(4) + " m, omega = " + omega.toFixed(2) + " rad/s, T = " + (2 * Math.PI / omega).toFixed(3) + " s, amax = " + (A * omega * omega).toFixed(2) + " m/s^2 (contact needs amax below 9.8)";
